-- Generated by drizzle-kit, plus a hand-written cleanup (gap review P-7): keep only the
-- newest open overstay checkout per booking before the one-open rule applies.
update public.payments p
   set status = 'ABANDONED', updated_at = now()
 where p.kind = 'OVERSTAY' and p.status = 'PENDING'
   and exists (
     select 1 from public.payments newer
      where newer.booking_id = p.booking_id and newer.kind = 'OVERSTAY'
        and newer.status = 'PENDING'
        and (newer.created_at, newer.id) > (p.created_at, p.id)
   );
--> statement-breakpoint
CREATE UNIQUE INDEX "payments_one_open_overstay_idx" ON "payments" USING btree ("booking_id") WHERE "payments"."kind" = 'OVERSTAY' and "payments"."status" = 'PENDING';